        // Writes data\xray\config.json: a local SOCKS inbound whose freedom
        // outbound applies TCP fragmentation to every connection. tor sends all
        // of its guard/bridge TLS through this SOCKS proxy (Socks5Proxy in
        // torrc), so the split ClientHello hides the Tor handshake from
        // packet-length/SNI based DPI. Two stacked fragment layers: the first
        // splits only the tlshello, the second re-splits the remaining stream.
        private static bool WriteXrayConfig()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(XrayConfig));
                string json =
                    "{\n" +
                    "  \"log\": { \"loglevel\": \"warning\" },\n" +
                    "  \"inbounds\": [\n" +
                    "    {\n" +
                    "      \"listen\": \"127.0.0.1\",\n" +
                    "      \"port\": " + FragmentSocksPort + ",\n" +
                    "      \"protocol\": \"socks\",\n" +
                    "      \"settings\": { \"auth\": \"noauth\", \"udp\": true }\n" +
                    "    }\n" +
                    "  ],\n" +
                    "  \"outbounds\": [\n" +
                    "    {\n" +
                    "      \"protocol\": \"freedom\",\n" +
                    "      \"settings\": {\n" +
                    "        \"tcp\": [\n" +
                    "          {\n" +
                    "            \"type\": \"fragment\",\n" +
                    "            \"settings\": {\n" +
                    "              \"packets\": \"tlshello\",\n" +
                    "              \"lengths\": [\"5\", \"94\", \"1\"],\n" +
                    "              \"delays\": [\"0\"],\n" +
                    "              \"maxSplit\": \"0\"\n" +
                    "            }\n" +
                    "          },\n" +
                    "          {\n" +
                    "            \"type\": \"fragment\",\n" +
                    "            \"settings\": {\n" +
                    "              \"packets\": \"1-1\",\n" +
                    "              \"lengths\": [\"109\", \"1\"],\n" +
                    "              \"delays\": [\"1\"],\n" +
                    "              \"maxSplit\": \"355\"\n" +
                    "            }\n" +
                    "          }\n" +
                    "        ]\n" +
                    "      },\n" +
                    "      \"streamSettings\": { \"sockopt\": { \"tcpNoDelay\": true } }\n" +
                    "    }\n" +
                    "  ]\n" +
                    "}\n";
                File.WriteAllText(XrayConfig, json, new UTF8Encoding(false));
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("[x] failed to write xray config: " + ex.Message);
                return false;
            }
        }

        private static bool StartXray()
        {
            try
            {
                if (!File.Exists(XrayExe))
                {
                    Console.WriteLine("[!] xray.exe not found in " + DataDir +
                                      " - fragment disabled for this run.");
                    return false;
                }
                if (!File.Exists(XrayConfig))
                {
                    if (!WriteXrayConfig()) return false;
                    Console.WriteLine("no data\\xray\\config.json found - wrote a default one.");
                }
                ProcessStartInfo psi = new ProcessStartInfo
                {
                    FileName = XrayExe,
                    Arguments = "run -c xray\\config.json",
                    WorkingDirectory = DataDir,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };
                Process p = Process.Start(psi);
                xrayProc = p;
                Console.WriteLine("xray (fragment) started (PID " + p.Id +
                                  ") on 127.0.0.1:" + FragmentSocksPort +
                                  " using xray\\config.json");
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine("[x] failed to start xray: " + ex.Message);
                return false;
            }
        }

        private static void StopXray()
        {
            Process p = xrayProc;
            xrayProc = null;
            if (p != null)
            {
                try { if (!p.HasExited) { p.Kill(); p.WaitForExit(5000); } }
                catch { }
            }
            p = FindXray();
            if (p != null)
            {
                try { p.Kill(); p.WaitForExit(5000); } catch { }
            }
        }

        // Strategy for a run: env override (bench) > saved choice > ultimate.
        private static int ResolveStrategy()
        {
            string env = Environment.GetEnvironmentVariable("BENCH_STRATEGY");
            if (!string.IsNullOrEmpty(env))
            {
                int s = ParseStrategy(env);
                if (s >= 0) return s;
            }
            int last = ReadLastStrategy();
            return last >= 0 ? last : StrategyNames.Length - 1;
        }

        private static int ShowMenu()
        {
            int last = ReadLastMode();
            while (true)
            {
                Console.WriteLine();
                Console.WriteLine("  Connection mode:");
                Console.WriteLine("    1) Vanilla");
                Console.WriteLine("    2) Obfs4");
                Console.WriteLine("    3) WebTunnel");
                Console.WriteLine("    4) Snowflake");
                Console.WriteLine("    5) Direct Tor");
                Console.Write("  Choose 1-5 (Enter = " + ModeNames[last >= 0 ? last : 0] + "): ");
                string input;
                try { input = Console.ReadLine(); }
                catch { return -1; }
                if (string.IsNullOrWhiteSpace(input)) return last >= 0 ? last : 0;
                int n;
                if (int.TryParse(input.Trim(), out n) && n >= 1 && n <= 5) return n - 1;
                int m = ParseMode(input.Trim());
                if (m >= 0) return m;
                Console.WriteLine("    Invalid choice, try again.");
            }
        }

        private static int ShowStrategyMenu()
        {
            int last = ReadLastStrategy();
            while (true)
            {
                Console.WriteLine();
                Console.WriteLine("  Strategy level:");
                for (int i = 0; i < StrategyNames.Length; i++)
                {
                    string star = i == 0 ? "" : "  ";
                    Console.WriteLine("    " + (i + 1) + ") " + StrategyNames[i].PadRight(10) +
                                      " - " + StrategyDesc[i]);
                }
                Console.Write("  Choose 1-" + StrategyNames.Length +
                              " (Enter = " + StrategyNames[last >= 0 ? last : StrategyNames.Length - 1] + "): ");
                string input;
                try { input = Console.ReadLine(); }
                catch { return -1; }
                if (string.IsNullOrWhiteSpace(input)) return last >= 0 ? last : StrategyNames.Length - 1;
                int n;
                if (int.TryParse(input.Trim(), out n) && n >= 1 && n <= StrategyNames.Length) return n - 1;
                int s = ParseStrategy(input.Trim());
                if (s >= 0) return s;
                Console.WriteLine("    Invalid choice, try again.");
            }
        }

        private static void WriteModeFile(int mode)
        {
