            catch { }
        }

        // Interactive startup: pick connection mode and strategy level, then start.
        private static void ShowMainMenu(out int mode, out int strategy, out bool fragment)
        {
            mode = ReadLastMode();
            if (mode < 0) mode = 0;
            strategy = ReadLastStrategy();
            if (strategy < 0) strategy = StrategyNames.Length - 1;
            fragment = ReadFragmentSetting();
            while (true)
            {
                Console.WriteLine();
                Console.WriteLine("  ====================");
                Console.WriteLine("     TorJet v" + TorJetVersion.App);
                Console.WriteLine("  ====================");
                Console.WriteLine("    0) Start Tor");
                Console.WriteLine("    1) Connection mode   : " + ModeNames[mode]);
                Console.WriteLine("    2) Strategy level    : " + StrategyNames[strategy]);
                Console.WriteLine("    3) Fragment (xray)   : " + (fragment ? "on" : "off"));
                Console.WriteLine("    4) Exit");
                Console.WriteLine("    C) Stop Tor and return to menu");
                Console.Write("  Choose 0-4, C (Enter = 0): ");
                string input;
                try { input = Console.ReadLine(); }
                catch { mode = -1; return; }
                if (string.IsNullOrWhiteSpace(input)) return;
                int n;
                if (int.TryParse(input.Trim(), out n))
                {
                    if (n == 0) return;
                    if (n == 1)
                    {
                        int m = ShowMenu();
                        if (m >= 0) { mode = m; WriteModeFile(mode); }
                    }
                    else if (n == 2)
                    {
                        int s = ShowStrategyMenu();
                        if (s >= 0) { strategy = s; WriteStrategyFile(strategy); }
                    }
                    else if (n == 3)
                    {
                        fragment = !fragment;
                        WriteFragmentFile(fragment);
                    }
                    else if (n == 4) { mode = -1; return; }
                    else Console.WriteLine("    Invalid choice, try again.");
                }
                else if (input.Trim().Equals("c", StringComparison.OrdinalIgnoreCase))
                {
                    StopTor();
                }
                else
                {
                    int m = ParseMode(input.Trim());
                    if (m >= 0) { mode = m; WriteModeFile(mode); }
                    else
                    {
                        int s = ParseStrategy(input.Trim());
                        if (s >= 0) { strategy = s; WriteStrategyFile(strategy); }
                        else Console.WriteLine("    Invalid choice, try again.");
                    }
                }
            }
        }

        private static bool WriteTorrc(int mode, int strategy, bool fragment)
        {
            if (!File.Exists(TorrcTemplate))
            {
                Console.WriteLine("[x] torrc.template not found in " + DataDir);
                return false;
            }
            string tmpl = File.ReadAllText(TorrcTemplate);
            int bridgeCount = 0;
            StringBuilder sb = new StringBuilder(tmpl.TrimEnd());
            if (BridgeFiles[mode].Length > 0)
            {
                string bf = Path.Combine(BridgesDir, BridgeFiles[mode]);
                if (!File.Exists(bf))
                {
                    Console.WriteLine("[x] bridge file not found: " + bf);
                    return false;
                }
                var bridges = new List<string>();
                foreach (string line in File.ReadAllLines(bf))
                {
                    string t = line.Trim();
                    if (t.Length == 0 || t.StartsWith("#")) continue;
                    bridges.Add("Bridge " + t);
                }
                if (bridges.Count == 0)
                {
                    Console.WriteLine("[!] no usable bridge lines in " + bf);
                    return false;
                }
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- bridges: " + ModeNames[mode] + " ---");
                sb.AppendLine("UseBridges 1");
                foreach (string b in bridges) sb.AppendLine(b);
                bridgeCount = bridges.Count;
            }
            if (strategy >= 0 && strategy < StrategyNames.Length && StrategyTorrc[strategy].Length > 0)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- strategy: " + StrategyNames[strategy] + " ---");
                foreach (string line in StrategyTorrc[strategy]) sb.AppendLine(line);
            }
            if (fragment)
            {
                sb.AppendLine();
                sb.AppendLine();
                sb.AppendLine("# --- tlshello fragment via local xray (see config.json) ---");
                sb.AppendLine("Socks5Proxy 127.0.0.1:" + FragmentSocksPort);
            }
            File.WriteAllText(Torrc, sb.ToString(), new UTF8Encoding(false));
            try { File.WriteAllText(ModeFile, ModeNames[mode], new UTF8Encoding(false)); }
            catch { }
            try { WriteStrategyFile(strategy); }
            catch { }
            Console.WriteLine("torrc written (" + ModeNames[mode] +
                              ", strategy " + StrategyNames[strategy] +
                              (BridgeFiles[mode].Length > 0 ? ", " + bridgeCount + " bridges" : "") +
                              (fragment ? ", fragment on" : "") + ")");
            return true;
        }

        private static int CountBridgeLines(string path)
        {
            int n = 0;
            foreach (string line in File.ReadAllLines(path))
            {
                string t = line.Trim();
                if (t.Length == 0 || t.StartsWith("#")) continue;
                if (t.Contains("2001:db8")) continue;
                n++;
            }
            return n;
        }

        private static int UpdateBridges()
        {
            try
            {
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
            }
            catch { }

            Directory.CreateDirectory(BridgesDir);
            Console.WriteLine("Updating bridge files from " + BridgesBaseUrl);
            Console.WriteLine("  -> " + BridgesDir);
            Console.WriteLine();

            int ok = 0;
            foreach (string f in AllBridgeFiles)
            {
                string dest = Path.Combine(BridgesDir, f);
                string tmp = dest + ".tmp";
                string url = BridgesBaseUrl + "/" + f;
                try
                {
                    using (WebClient wc = new WebClient())
                    {
                        wc.Headers[HttpRequestHeader.UserAgent] = "torjet-updater/1.0";
                        wc.DownloadFile(url, tmp);
                    }
                    int n = CountBridgeLines(tmp);
                    if (n == 0)
                    {
                        Console.WriteLine("[!] " + f + ": downloaded file has no usable bridges - keeping old.");
                        try { File.Delete(tmp); } catch { }
                        continue;
                    }
                    File.Copy(tmp, dest, true);
                    try { File.Delete(tmp); } catch { }
                    Console.WriteLine("" + f + ": " + n + " bridges - updated.");
                    ok++;
                }
                catch (Exception ex)
                {
                    Console.WriteLine("[x] " + f + ": " + ex.Message);
                }
            }

            Console.WriteLine();
            if (ok == AllBridgeFiles.Length)
            {
                Console.WriteLine("All bridge files are up to date.");
                return 0;
            }
            Console.WriteLine("Updated " + ok + " of " + AllBridgeFiles.Length +
                              " bridge files (restart tor to use the new bridges).");
            return ok > 0 ? 0 : 1;
        }

        private static string FormatSpeed(double bytesPerSec)
        {
            if (bytesPerSec >= 1024 * 1024)
                return (bytesPerSec / (1024 * 1024)).ToString("0.00") + " MB/s";
            if (bytesPerSec >= 1024)
                return (bytesPerSec / 1024).ToString("0.0") + " KB/s";
            return bytesPerSec.ToString("0") + " B/s";
        }

        private static void SpeedTest()
        {
            try { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; }
            catch { }

            Console.WriteLine();
            Console.WriteLine("Speed test: downloading 10 MB through Tor (HTTP 127.0.0.1:8118)...");
            try
            {
                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                    "https://speed.cloudflare.com/__down?bytes=10000000");
                req.Proxy = new WebProxy("127.0.0.1", 8118);
                req.Method = "GET";
                req.Timeout = 60000;
                req.ReadWriteTimeout = 60000;
                req.UserAgent = "torjet-speedtest/1.0";

                using (WebResponse resp = req.GetResponse())
                using (Stream s = resp.GetResponseStream())
                {
                    byte[] buf = new byte[64 * 1024];
                    long total = 0;
                    Stopwatch sw = Stopwatch.StartNew();
                    long lastBytes = 0;
                    long lastTicks = sw.ElapsedTicks;
                    double inst = 0;
                    int n;
                    while ((n = s.Read(buf, 0, buf.Length)) > 0)
                    {
                        total += n;
                        long now = sw.ElapsedTicks;
                        if (now - lastTicks >= Stopwatch.Frequency)
                        {
                            inst = (total - lastBytes) /
                                   ((now - lastTicks) / (double)Stopwatch.Frequency);
                            lastBytes = total;
                            lastTicks = now;
                            Console.WriteLine("    " + total.ToString("#,0") + " bytes  (" + FormatSpeed(inst) + ")");
                        }
                    }
                    sw.Stop();

                    if (total > lastBytes)
                        inst = (total - lastBytes) /
                               ((sw.ElapsedTicks - lastTicks) / (double)Stopwatch.Frequency);
                    double avg = total / sw.Elapsed.TotalSeconds;

                    Console.WriteLine();
                    Console.WriteLine("Done: " + total.ToString("#,0") + " bytes in " +
                                      sw.Elapsed.TotalSeconds.ToString("0.0") + " s");
                    Console.WriteLine("  average speed    : " + FormatSpeed(avg));
                    Console.WriteLine("  instantaneous    : " + FormatSpeed(inst));
                    Console.WriteLine("  (avg MB/s = " + (avg / (1024 * 1024)).ToString("0.00") + ")");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("[x] speed test failed: " + ex.Message);
            }
        }

        // Opens a raw SOCKS5 (RFC 1928) connection through Tor's SOCKS port
        // (127.0.0.1:9050). A unique `username` per connection makes tor's
        // IsolateSOCKSAuth isolation give every stream its own circuit, which is
        // what turns N parallel downloads into N parallel Tor paths instead of
        // N streams sharing one circuit.
        private static NetworkStream Socks5Connect(string host, int port, string username)
        {
            TcpClient tc = new TcpClient();
            tc.Connect(IPAddress.Loopback, 9050);
            NetworkStream ns = tc.GetStream();
            ns.ReadTimeout = 90000;
            ns.WriteTimeout = 90000;
            // greeting: VER=5, NMETHODS=2, methods = no-auth(0), user/pass(2)
            byte[] g = { 5, 2, 0, 2 };
            ns.Write(g, 0, g.Length);
            byte[] gm = new byte[2];
            if (ns.Read(gm, 0, 2) != 2 || gm[0] != 5) { tc.Close(); return null; }
            if (gm[1] == 2)
            {
                byte[] u = Encoding.UTF8.GetBytes(username);
                byte[] p = Encoding.UTF8.GetBytes("torb");
                ns.WriteByte(1);
                ns.WriteByte((byte)u.Length);
                ns.Write(u, 0, u.Length);
                ns.WriteByte((byte)p.Length);
                ns.Write(p, 0, p.Length);
                byte[] au = new byte[2];
                if (ns.Read(au, 0, 2) != 2 || au[1] != 0) { tc.Close(); return null; }
            }
            else if (gm[1] != 0)
            {
                tc.Close();
                return null;
            }
            byte[] hb = Encoding.ASCII.GetBytes(host);
            List<byte> req = new List<byte>();
            req.Add(5); req.Add(1); req.Add(0); req.Add(3); req.Add((byte)hb.Length);
            req.AddRange(hb);
            req.Add((byte)(port >> 8)); req.Add((byte)(port & 0xff));
            byte[] rq = req.ToArray();
            ns.Write(rq, 0, rq.Length);
            byte[] rh = new byte[4];
            if (ns.Read(rh, 0, 4) != 4 || rh[0] != 5 || rh[1] != 0) { tc.Close(); return null; }
            int atyp = rh[3];
            int skip = atyp == 1 ? 6 : atyp == 4 ? 18 : 0;
            if (atyp == 3) { skip = ns.ReadByte() + 2; }
            for (int i = 0; i < skip; i++) ns.ReadByte();
            return ns;
        }

        // Downloads `bytes` from host over a freshly established SOCKS5 stream
        // (username gives it an isolated circuit). Returns bytes received.
        private static long SocksDownload(string host, string username, long bytes)
        {
            try
            {
                NetworkStream ns = Socks5Connect(host, 443, username);
                if (ns == null) return -1;
                using (var ssl = new System.Net.Security.SslStream(ns))
                {
                    ssl.ReadTimeout = 90000;
                    ssl.WriteTimeout = 90000;
                    ssl.AuthenticateAsClient(host, null,
                        System.Security.Authentication.SslProtocols.Tls12, false);
                    byte[] req = Encoding.ASCII.GetBytes(
                        "GET /__down?bytes=" + bytes + " HTTP/1.1\r\n" +
                        "Host: " + host + "\r\n" +
                        "User-Agent: torjet-speedtest/1.0\r\n" +
                        "Connection: close\r\n\r\n");
                    ssl.Write(req, 0, req.Length);
                    ssl.Flush();
                    byte[] buf = new byte[64 * 1024];
                    long total = 0;
                    int n;
                    while ((n = ssl.Read(buf, 0, buf.Length)) > 0) total += n;
                    return total;
                }
            }
            catch { return -1; }
        }

        // The "ultimate" speed test: N parallel SOCKS5 streams, each with its own
        // username -> its own circuit. This is the max-throughput configuration
        // the strategies are aiming for.
        private static void MultiSpeedTest(int streams)
        {
            Console.WriteLine();
            Console.WriteLine("Max speed test: " + streams + " parallel streams " +
                              "(each on its own circuit via SOCKS5 auth)...");
            string host = "speed.cloudflare.com";
            long target = 10L * 1024 * 1024;
            long total = 0;
            var lockObj = new object();
            var errors = new List<string>();
            var threads = new List<Thread>();
            Stopwatch sw = Stopwatch.StartNew();
            for (int i = 0; i < streams; i++)
            {
                string user = "torb" + i; // unique -> isolated circuit
                Thread th = new Thread(delegate()
                {
                    long got = SocksDownload(host, user, target);
                    if (got < 0)
                    {
                        lock (lockObj) { if (errors.Count == 0) errors.Add("stream " + user + " failed"); }
                        got = 0;
                    }
                    Interlocked.Add(ref total, got);
                });
                th.IsBackground = true;
                threads.Add(th);
                th.Start();
            }
            foreach (Thread th in threads) th.Join();
            sw.Stop();
            double avg = total / sw.Elapsed.TotalSeconds;
            Console.WriteLine("Done: " + total.ToString("#,0") + " bytes in " +
                              sw.Elapsed.TotalSeconds.ToString("0.0") + " s");
            Console.WriteLine("  aggregate average : " + FormatSpeed(avg));
            if (errors.Count > 0) Console.WriteLine("  " + errors.Count + " of " + streams + " streams failed");
        }

        private static void SpeedTestMenu()
        {
            Console.WriteLine();
            Console.WriteLine("  Speed test:");
            Console.WriteLine("    1) Single stream (HTTP 8118)");
            Console.WriteLine("    2) Max: " + StrategyNames.Length + "+ parallel SOCKS5 streams, each own circuit");
            Console.Write("  Choose 1-2 (Enter = 2): ");
            string input;
            try { input = Console.ReadLine(); }
            catch { input = "2"; }
            if (string.IsNullOrWhiteSpace(input)) input = "2";
            int n;
            if (!int.TryParse(input.Trim(), out n)) n = 2;
            if (n == 1) SpeedTest();
            else MultiSpeedTest(4);
        }

        // --- benchmark / conflux diagnostics (step 0 harness) --------------

        private static byte[] HexToBytes(string hex)
        {
            byte[] b = new byte[hex.Length / 2];
            for (int i = 0; i < b.Length; i++)
                b[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            return b;
        }

        // Sends a command to the tor control port and returns every raw reply
        // line, including the terminating status line ("250 OK" and friends).
        // Returns null when the port is unreachable or auth fails.
        private static List<string> ControlRaw(string cmd)
        {
            try
            {
                string hex = CookieHex();
                if (hex == null) return null;
                using (TcpClient c = new TcpClient("127.0.0.1", 9051))
                {
                    NetworkStream s = c.GetStream();
                    StreamWriter w = new StreamWriter(s) { NewLine = "\r\n", AutoFlush = true };
                    StreamReader r = new StreamReader(s);
                    w.WriteLine("AUTHENTICATE " + hex);
                    string a = r.ReadLine();
                    if (a == null || !a.StartsWith("250")) return null;
                    w.WriteLine(cmd);
                    var lines = new List<string>();
                    string line;
                    while ((line = r.ReadLine()) != null)
                    {
                        lines.Add(line);
                        // A reply ends at any status line: "250 OK", "250 ...",
                        // or an error line like "510 ...", "552 ...".
                        if (line.Length >= 4 && line[0] >= '0' && line[0] <= '9' &&
                            line[1] >= '0' && line[1] <= '9' &&
                            line[2] >= '0' && line[2] <= '9' && line[3] == ' ')
                            break;
                    }
                    try { w.WriteLine("QUIT"); } catch { }
                    return lines;
                }
            }
            catch { return null; }
        }

        // Sends a command to the tor control port and returns the response
        // payload lines (without the terminating status line).
        private static List<string> ControlCommand(string cmd)
        {
            var raw = ControlRaw(cmd);
            if (raw == null) return null;
            var lines = new List<string>();
            foreach (string line in raw)
            {
                if (line.StartsWith("250 ")) break;
                if (line.StartsWith("250-")) lines.Add(line.Substring(4));
                else if (line.StartsWith("250+")) lines.Add(line.Substring(4));
            }
            return lines;
        }

        // Returns the numeric status code of a control command ("250", "552", ...)
        // or -1 when the port is unreachable or auth fails.
        private static int ControlStatus(string cmd)
        {
            var raw = ControlRaw(cmd);
            if (raw == null) return -1;
            foreach (string line in raw)
            {
                int sp = line.IndexOf(' ');
                if (sp > 0)
                {
                    int code;
                    if (int.TryParse(line.Substring(0, sp), out code)) return code;
                }
            }
            return -1;
        }

        // Returns the value of a "KEY=value" token in a space-separated line.
        private static string Token(string line, string key)
        {
            string p = key + "=";
            foreach (string tok in line.Split(' '))
                if (tok.StartsWith(p)) return tok.Substring(p.Length);
            return null;
        }

        // Advertised bandwidth (bytes/s) of an exit, from GETINFO ns/id/<fp>.
        private static string ExitBandwidth(string fpHex)
        {
            try
            {
                fpHex = fpHex.TrimStart('$');
                if (fpHex == "?" || fpHex.Length != 40) return "?";
                var lines = ControlCommand("GETINFO ns/id/" + fpHex);
                if (lines == null) return "?";
                foreach (string raw in lines)
                {
                    string line = raw.Trim();
                    if (line.StartsWith("w "))
                    {
                        Match m = Regex.Match(line, "Bandwidth=(\\d+)");
                        if (m.Success) return m.Groups[1].Value;
                    }
                }
            }
            catch { }
            return "?";
        }

        // Reads the CONFLUX QUERY output, one entry per leg circuit. Every entry
        // is { set, circ, exit, legs, state, rttUs }. Returns null when the tor
        // control port can't be reached.
        private static List<string[]> ConfluxQuery()
        {
            var lines = ControlCommand("CONFLUX QUERY");
            if (lines == null) return null;
            var legs = new List<string[]>();
            foreach (string raw in lines)
            {
                string line = raw.Trim();
                if (line.Length == 0) continue;
                if (line.StartsWith("CONFLUX status", StringComparison.OrdinalIgnoreCase)) continue;
                string set = Token(line, "SET");
                if (set == null) continue;
                string exit = Token(line, "EXIT");
                string state = Token(line, "STATE");
                int legsN = 0, rttUs = 0;
                int.TryParse(Token(line, "LEGS"), out legsN);
                int.TryParse(Token(line, "RTT_US"), out rttUs);
                legs.Add(new[] { set, Token(line, "CIRC") == null ? "?" : Token(line, "CIRC"),
                                 exit == null ? "?" : exit, legsN.ToString(),
                                 state == null ? "?" : state, rttUs.ToString() });
            }
            return legs;
        }

        // Counts conflux sets/legs and returns the exit of the first set.
        private static string ConfluxInfo(out int sets, out int legs)
        {
            sets = 0;
            legs = 0;
            string exit = "?";
            var legList = ConfluxQuery();
            if (legList == null) return exit;
            var legCount = new Dictionary<string, int>();
            foreach (string[] leg in legList)
            {
                if (!legCount.ContainsKey(leg[0])) legCount[leg[0]] = 0;
                legCount[leg[0]]++;
                if (exit == "?" && leg[2] != "?" && leg[2] != null) exit = leg[2];
            }
            sets = legCount.Count;
            foreach (int n in legCount.Values) legs += n;
            return exit;
        }

        // Adds a new leg to a conflux set via the CONFLUX ADD control command
        // (TorJet extension). With no set id it targets the first set found, or
        // prompts when several sets exist.
        private static int AddConfluxLeg(string setId)
        {
            var legList = ConfluxQuery();
            if (legList == null)
            {
                Console.WriteLine("[x] cannot reach tor control port on 127.0.0.1:9051 (is tor running?).");
                return 1;
            }
            if (legList.Count == 0)
            {
                Console.WriteLine("[x] no conflux set to extend - conflux is NOT engaging (check consensus support).");
                return 1;
            }
            var sets = new Dictionary<string, List<string[]>>();
            foreach (string[] leg in legList)
            {
                if (!sets.ContainsKey(leg[0])) sets[leg[0]] = new List<string[]>();
                sets[leg[0]].Add(leg);
            }
            if (string.IsNullOrEmpty(setId))
            {
                if (sets.Count > 1)
                {
                    Console.WriteLine("  Multiple conflux sets; pick one:");
                    int i = 1;
                    foreach (var kv in sets)
                    {
                        Console.WriteLine("    " + i + ") " + kv.Key + " (" + kv.Value.Count + " legs)");
                        i++;
                    }
                    Console.Write("  Set number (Enter = 1): ");
                    string input;
                    try { input = Console.ReadLine(); }
                    catch { return 1; }
                    if (string.IsNullOrWhiteSpace(input))
                    {
                        foreach (var kv in sets) { setId = kv.Key; break; }
                    }
                    else
                    {
                        int n;
                        if (!int.TryParse(input.Trim(), out n) || n < 1 || n > sets.Count)
                        {
                            Console.WriteLine("    Invalid choice.");
                            return 1;
                        }
                        i = 1;
                        foreach (var kv in sets) { if (i == n) { setId = kv.Key; break; } i++; }
                    }
                }
                else
                {
                    foreach (var kv in sets) setId = kv.Key;
                }
            }
            if (!sets.ContainsKey(setId))
            {
                Console.WriteLine("[x] no conflux set \"" + setId + "\" - use a SET= id from CONFLUX QUERY.");
                return 1;
            }
            int status = ControlStatus("CONFLUX ADD " + setId);
            if (status == 250)
                Console.WriteLine("  Added a leg to conflux set " + setId + " - tor is building it.");
            else
                Console.WriteLine("[x] CONFLUX ADD " + setId + " failed (status " + status + ").");
            return status == 250 ? 0 : 1;
        }

        private static int ConfluxStatus()
        {
            var legList = ConfluxQuery();
            if (legList == null)
            {
                Console.WriteLine("[x] cannot reach tor control port on 127.0.0.1:9051 (is tor running?).");
                return 1;
            }
            bool debug = Environment.GetEnvironmentVariable("BENCH_DEBUG") == "1";
            Console.WriteLine();
            Console.WriteLine("Conflux status:");
            if (legList.Count == 0)
            {
                Console.WriteLine("  NO conflux circuits - conflux is NOT engaging (check consensus support).");
                return 1;
            }
            var sets = new Dictionary<string, List<string[]>>();
            foreach (string[] leg in legList)
            {
                if (!sets.ContainsKey(leg[0])) sets[leg[0]] = new List<string[]>();
                sets[leg[0]].Add(leg);
            }
            int legs = legList.Count;
            Console.WriteLine("  conflux sets      : " + sets.Count);
            Console.WriteLine("  conflux legs      : " + legs);
            int idx = 1;
            foreach (var kv in sets)
            {
                int bestUs = int.MaxValue;
                string exit = "?";
                int linked = 0;
                foreach (string[] leg in kv.Value)
                {
                    if (leg[2] != "?") exit = leg[2];
                    if (leg[4] == "LINKED")
                    {
                        linked++;
                        int rttUs;
                        if (int.TryParse(leg[5], out rttUs) && rttUs > 0 && rttUs < bestUs)
                            bestUs = rttUs;
                    }
                }
                string rtt = bestUs == int.MaxValue ? "?" : (bestUs / 1000) + " ms";
                Console.WriteLine("    set " + idx + ": " + kv.Value.Count + " leg(s) (" + linked +
                                  " linked), exit " + exit + ", best RTT " + rtt);
                if (debug)
                {
                    foreach (string[] leg in kv.Value)
                    {
                        int rttUs;
                        string r = int.TryParse(leg[5], out rttUs) && rttUs > 0
                                       ? (rttUs / 1000) + " ms" : "?";
                        Console.WriteLine("      [leg] circ " + leg[1] + " " + leg[4] + " RTT " + r);
                    }
                    Console.WriteLine("      [bw] exit bandwidth: " + ExitBandwidth(exit) + " bytes/s");
                }
                idx++;
            }
            Console.WriteLine("  conflux is ACTIVE (" + sets.Count + " set(s), " + legs + " leg(s)).");
            return 0;
        }

        // Background circuit health monitor. Every watchIntervalS seconds it
        // asks tor (CONFLUX QUERY) and closes the weakest half (rounded up) of
        // the conflux legs whose RTT is above watchRttMs. tor then builds
        // replacement legs and conflux migrates any streams off the closed
        // ones. Non-conflux circuits are left alone. A watchCooldownS-second
        // gap between closes prevents circuit churn (relaxed during warmup).
        private static void CircuitWatchLoop()
        {
            DateTime lastClose = DateTime.MinValue;
            while (!circuitWatchStop)
            {
                Thread.Sleep(TimeSpan.FromSeconds(watchIntervalS));
                if (circuitWatchStop) break;
                if (torProc == null) continue;
                try { torProc.Refresh(); if (torProc.HasExited) break; }
                catch { break; }
                if (!circuitWatchWarmup &&
                    DateTime.UtcNow - lastClose < TimeSpan.FromSeconds(watchCooldownS)) continue;
                var legList = ConfluxQuery();
                if (legList == null) continue;

                // Collect every linked conflux leg with a measured RTT.
                var legs = new List<string[]>();
                foreach (string[] leg in legList)
                {
                    if (!leg[4].Equals("LINKED", StringComparison.OrdinalIgnoreCase)) continue;
                    int rttUs;
                    if (!int.TryParse(leg[5], out rttUs) || rttUs <= 0) continue;
                    legs.Add(new[] { leg[1], rttUs.ToString() });
                }
                if (legs.Count == 0) continue;

                // The weak legs are those at/above the RTT threshold. Sort them
                // worst first and close the weakest half (rounded up), so with
                // 4 slow legs the 2 weakest go in one pass. Healthy legs are
                // never touched.
                var weak = new List<string[]>();
                foreach (string[] leg in legs)
                {
                    if (int.Parse(leg[1]) >= watchRttMs * 1000) weak.Add(leg);
                }
                if (weak.Count == 0) continue;
                weak.Sort(delegate(string[] a, string[] b)
                {
                    return int.Parse(b[1]) - int.Parse(a[1]);
                });
                int removeCount = (int)Math.Ceiling(weak.Count / 2.0);
                var toRemove = weak.GetRange(0, removeCount);
                var toRemoveIds = new HashSet<string>();
                foreach (string[] leg in toRemove) toRemoveIds.Add(leg[0]);

                lock (consoleLock)
                {
                    ClearProgressLine();
                    Console.WriteLine("circuit monitor: conflux legs:");
                    foreach (string[] leg in legs)
                    {
                        string mark = toRemoveIds.Contains(leg[0]) ? "   <-- removing (weakest)" : "";
                        Console.WriteLine("    leg " + leg[0] + "  RTT " +
                                          (int.Parse(leg[1]) / 1000) + " ms" + mark);
                    }
                    int closed = 0;
                    string closedIds = "";
                    foreach (string[] leg in toRemove)
                    {
                        if (ControlSend("CLOSECIRCUIT " + leg[0]))
                        {
                            closed++;
                            if (closedIds.Length > 0) closedIds += ", ";
                            closedIds += leg[0];
                        }
                    }
                    if (closed > 0)
                    {
                        lastClose = DateTime.UtcNow;
                        Console.WriteLine("circuit monitor: closed " + closed + " weak leg" +
                                          (closed > 1 ? "s" : "") + " (" + closedIds +
                                          ") - replacement is being built.");
                    }
                }
            }
        }

        // Returns tor's own bootstrap status. Two sources are used and the more
        // advanced one wins:
        //   - the control port (GETINFO status/bootstrap-phase) is authoritative;
        //   - the log fallback ("Bootstrapped NN% (tag)") covers the window
        //     before the control port answers and guards against the launcher
        //     missing the 100% line because it scrolled out of the log tail.
        // tor.log is deleted before every start, so a stale "100%" from an older
        // run can never be misread as the current run's status.
        // Returns false when neither source has a percentage yet.
        private static bool BootstrapPhase(out int pct, out string tag, out string summary)
        {
            pct = -1;
            tag = "";
            summary = "";
            int ctl = -1, log = -1;
            string ctlTag = "", logTag = "", ctlSummary = "";

            var lines = ControlCommand("GETINFO status/bootstrap-phase");
            if (lines != null)
            {
                foreach (string raw in lines)
                {
                    string l = raw.Trim();
                    if (l.Length == 0) continue;
                    Match m = Regex.Match(l, @"PROGRESS=(\d+)");
                    if (m.Success)
                    {
                        ctl = int.Parse(m.Groups[1].Value);
                        Match t = Regex.Match(l, @"TAG=([^\s]+)");
                        if (t.Success) ctlTag = t.Groups[1].Value;
                        Match s = Regex.Match(l, @"SUMMARY=(.*)$");
                        if (s.Success) ctlSummary = s.Groups[1].Value.Trim('"');
                        break;
                    }
                }
            }

            string tail = ReadLogTail(8192);
            MatchCollection ms = Regex.Matches(tail, @"Bootstrapped\s+(\d+)%\s*(?:\(([^)]+)\))?");
            if (ms.Count > 0)
            {
                Match m = ms[ms.Count - 1];
                log = int.Parse(m.Groups[1].Value);
                if (m.Groups[2].Success) logTag = m.Groups[2].Value;
            }

            if (log > ctl)
            {
                pct = log;
                tag = logTag;
                return true;
            }
            if (ctl >= 0)
            {
                pct = ctl;
                tag = ctlTag;
                summary = ctlSummary;
                return true;
            }
            return false;
        }

        // Redraws the bootstrap progress bar on the current console line.
        // The percentage is snapped to 10% steps (0, 10, 20, ..., 100).
        private static void DrawProgress(int pct, string label)
        {
            lock (consoleLock)
            {
                const int width = 24;
                pct = (pct / 10) * 10;
                if (pct > 100) pct = 100;
                if (pct < 0) pct = 0;
                int filled = (int)Math.Round(pct / 100.0 * width);
                if (filled > width) filled = width;
                if (filled < 0) filled = 0;
                string bar = new string('#', filled) + new string('.', width - filled);
                string line = "    [" + bar + "] " + pct.ToString() + "%";
                if (!string.IsNullOrEmpty(label)) line += "  " + label;
                if (line.Length < progressLineLen) line = line.PadRight(progressLineLen);
                Console.Write("\r" + line);
                progressLineLen = line.Length;
            }
        }

        private static void ClearProgressLine()
        {
            lock (consoleLock)
            {
                if (progressLineLen > 0)
                {
                    Console.Write("\r" + new string(' ', progressLineLen) + "\r");
                    progressLineLen = 0;
                }
            }
        }

        // Starts tor for the given mode, writes torrc, stops any previous run,
        // and waits until bootstrap reaches 100%. Returns the process or null.
        // `aborted` is set when the user pressed C to stop during bootstrap.
        private static Process StartTorAndWait(int mode, int strategy, bool fragment,
                                               out string errorMessage, out bool aborted)
        {
            errorMessage = null;
            aborted = false;
            if (!File.Exists(TorExe))
            {
                errorMessage = "tor.exe not found in " + DataDir;
                return null;
            }
            StopPreviousRun();
            bool fragmentOn = fragment && File.Exists(XrayExe);
            if (fragmentOn)
            {
                if (!StartXray())
                {
                    fragmentOn = false;
                    Console.WriteLine("[!] fragment unavailable - continuing without it.");
                }
            }
            if (!WriteTorrc(mode, strategy, fragmentOn))
            {
                errorMessage = "failed to write torrc (bridge file missing?).";
                return null;
            }
            Directory.CreateDirectory(Path.Combine(DataDir, "data"));
            try { if (File.Exists(TorLog)) File.Delete(TorLog); } catch { }

            ProcessStartInfo psi = new ProcessStartInfo
            {
                FileName = TorExe,
                Arguments = "-f \"torrc\"",
                WorkingDirectory = DataDir,
                UseShellExecute = false,
                CreateNoWindow = true
            };
            Process proc;
            try { proc = Process.Start(psi); }
            catch (Exception ex)
            {
                errorMessage = "failed to start tor: " + ex.Message;
                return null;
            }
            torProc = proc;
            Console.WriteLine("tor started (PID " + proc.Id + "), bootstrapping...");

            DateTime deadline = DateTime.UtcNow.AddMinutes(10);
            int lastPct = -1;
            string lastTag = "";
            DateTime stuckSince = DateTime.UtcNow;
            while (DateTime.UtcNow < deadline)
            {
                try { proc.Refresh(); } catch { }
                if (proc.HasExited)
                {
                    ClearProgressLine();
                    errorMessage = "tor exited with code " + proc.ExitCode + ".\n" + ReadLogTail(1500);
                    return null;
                }
                try
                {
                    if (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.C)
                    {
                        ClearProgressLine();
                        try { proc.Kill(); } catch { }
                        aborted = true;
                        return null;
                    }
                }
                catch { }
                int pct;
                string tag;
                string summary;
                if (BootstrapPhase(out pct, out tag, out summary))
                {
                    if (pct >= 100)
                    {
                        DrawProgress(100, tag);
                        Console.WriteLine();
                        progressLineLen = 0;
                        return proc;
                    }
                    if (pct != lastPct)
                    {
                        lastPct = pct;
                        lastTag = tag;
                        stuckSince = DateTime.UtcNow;
                        DrawProgress(pct, tag);
                    }
                    else if (DateTime.UtcNow - stuckSince > TimeSpan.FromMinutes(3))
                    {
                        DrawProgress(pct, tag + "  (still waiting...)");
                    }
                    else
                    {
                        DrawProgress(pct, tag);
                    }
                }
                Thread.Sleep(1500);
            }
            ClearProgressLine();
            errorMessage = "bootstrap did not reach 100% in 10 minutes (last seen: " +
                           lastPct + "% " + lastTag + ").\n" + ReadLogTail(1500);
            return null;
        }

        private static string benchUrl;
        private static readonly string[] BenchEndpoints =
        {
            "https://speed.cloudflare.com/__down?bytes=10485760",
            "https://speed.hetzner.de/10MB.bin",
            "http://speedtest.tele2.net/10MB.zip"
        };

        // Lightweight endpoints that answer 204 No Content - perfect for
        // tunnel warmup pings through the proxy.
        private static readonly string[] PingEndpoints =
        {
            "https://www.gstatic.com/generate_204",
            "https://connectivitycheck.gstatic.com/generate_204",
            "https://cp.cloudflare.com/generate_204"
        };

        // Warms the tunnel with generate_204 pings through the HTTP proxy
        // (127.0.0.1:8118) instead of a 1 MiB download, which produced false
        // negatives on cold single-stream circuits. One request per second for
        // warmupSeconds, each with a 5 s timeout. Every request is timed and
        // counted; the tunnel is ready when at least 5 pings succeeded. C
        // aborts (stops tor, back to the main menu).
        private static bool WarmupTunnel()
        {
            try { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; }
            catch { }
            Console.WriteLine("warming tunnel: pinging generate_204 every second for " +
                              warmupSeconds + " s (C = stop Tor)...");
            int ok = 0, fail = 0, timeouts = 0;
            long totalMs = 0, bestMs = long.MaxValue, worstMs = 0;
            for (int i = 1; i <= warmupSeconds; i++)
            {
                bool success = false;
                bool anyTimeout = false;
                Stopwatch sw = Stopwatch.StartNew();
                foreach (string u in PingEndpoints)
                {
                    try
                    {
                        HttpWebRequest req = (HttpWebRequest)WebRequest.Create(u);
                        req.Proxy = new WebProxy("127.0.0.1", 8118);
                        req.Method = "GET";
                        req.Timeout = 5000;
                        req.ReadWriteTimeout = 5000;
                        req.UserAgent = "torjet-warmup/1.0";
                        using (WebResponse resp = req.GetResponse())
                        {
                            if ((int)((HttpWebResponse)resp).StatusCode < 400) { success = true; break; }
                        }
                    }
                    catch (WebException wex)
                    {
                        if (wex.Status == WebExceptionStatus.Timeout) anyTimeout = true;
                    }
                    catch { }
                }
                sw.Stop();
                long elapsedMs = sw.ElapsedMilliseconds;
                if (success)
                {
                    ok++;
                    totalMs += elapsedMs;
                    if (elapsedMs < bestMs) bestMs = elapsedMs;
                    if (elapsedMs > worstMs) worstMs = elapsedMs;
                }
                else if (anyTimeout) timeouts++;
                else fail++;

                string line = "warmup " + i + "/" + warmupSeconds + "  ok=" + ok +
                              "  fail=" + fail + "  avg=" + (ok > 0 ? totalMs / ok : 0) +
                              "ms  worst=" + worstMs + "ms";
                lock (consoleLock)
                {
                    if (line.Length < progressLineLen) line = line.PadRight(progressLineLen);
                    Console.Write("\r" + line);
                    progressLineLen = line.Length;
                }

                int wait = 1000 - (int)elapsedMs;
                if (wait > 0)
                {
                    for (int t = 0; t < wait / 100; t++)
                    {
                        Thread.Sleep(100);
                        try
                        {
                            if (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.C)
                            {
                                lock (consoleLock)
                                {
                                    ClearProgressLine();
                                    Console.WriteLine("warmup aborted (C) - stopping Tor.");
                                }
                                return false;
                            }
                        }
                        catch { }
                    }
                }
            }
            lock (consoleLock)
            {
                ClearProgressLine();
                Console.WriteLine();
                Console.WriteLine("warmup done: " + ok + " ok / " + fail + " fail / " + timeouts +
                                  " timeouts in " + warmupSeconds + " s - avg " +
                                  (ok > 0 ? totalMs / ok : 0) + " ms, best " +
                                  (bestMs == long.MaxValue ? "-" : bestMs.ToString()) +
                                  " ms, worst " + worstMs + " ms.");
                if (ok >= 5)
                {
                    long avg = ok > 0 ? totalMs / ok : 0;
                    if (avg > 3000)
                        Console.WriteLine("[!] tunnel is up but average ping is high (" +
                                          avg + " ms) - circuits may be slow.");
                }
                else
                {
                    Console.WriteLine("[!] tunnel could not be warmed (only " + ok +
                                      " successful pings) - stopping Tor.");
                }
            }
            return ok >= 5;
        }

        // Picks the first speed endpoint reachable through the proxy.
        private static void ProbeBenchUrl()
        {
            foreach (string u in BenchEndpoints)
            {
                try
                {
                    HttpWebRequest req = (HttpWebRequest)WebRequest.Create(u);
                    req.Proxy = new WebProxy("127.0.0.1", 8118);
                    req.Method = "GET";
                    req.Timeout = 30000;
                    req.ReadWriteTimeout = 30000;
                    req.UserAgent = "torjet-speedtest/1.0";
                    using (WebResponse resp = req.GetResponse())
                    using (Stream s = resp.GetResponseStream())
                    {
                        byte[] buf = new byte[16384];
                        if (s.Read(buf, 0, buf.Length) > 0)
                        {
                            benchUrl = u;
                            Console.WriteLine("speed endpoint OK: " + u);
                            return;
                        }
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine("endpoint failed (" + u + "): " + ex.Message);
                }
            }
            benchUrl = null;
            Console.WriteLine("[!] no speed endpoint reachable through the proxy.");
        }

        // Downloads `bytesPerStream` through the proxy on `streams` parallel
        // connections and reports aggregate throughput + peak sampled rate.
        private static void BenchDownload(int streams, long bytesPerStream,
                                          out long total, out double secs, out double peak)
        {
            long totalBytes = 0;
            long lastBytes = 0;
            double lastElapsed = 0;
            double peakRate = 0;
            var errors = new List<string>();
            Stopwatch sw = new Stopwatch();
            sw.Start();
            var threads = new List<Thread>();
            for (int i = 0; i < streams; i++)
            {
                Thread th = new Thread(delegate()
                {
                    long got = 0;
                    try
                    {
                        HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                            benchUrl ?? BenchEndpoints[0]);
                        req.Proxy = new WebProxy("127.0.0.1", 8118);
                        req.Method = "GET";
                        req.Timeout = 180000;
                        req.ReadWriteTimeout = 180000;
                        req.UserAgent = "torjet-speedtest/1.0";
                        using (WebResponse resp = req.GetResponse())
                        using (Stream s = resp.GetResponseStream())
                        {
                            byte[] buf = new byte[64 * 1024];
                            int n;
                            while ((n = s.Read(buf, 0, buf.Length)) > 0) got += n;
                        }
                    }
                    catch (Exception ex)
                    {
                        lock (errors) errors.Add(ex.Message);
                    }
                    Interlocked.Add(ref totalBytes, got);
                });
                th.IsBackground = true;
                threads.Add(th);
                th.Start();
            }
            while (true)
            {
                bool alive = false;
                foreach (Thread th in threads) if (th.IsAlive) { alive = true; break; }
                if (!alive) break;
                Thread.Sleep(200);
                double el = sw.Elapsed.TotalSeconds;
                long tb = Interlocked.Read(ref totalBytes);
                double dt = el - lastElapsed;
                if (dt >= 1.0)
                {
                    double rate = (tb - lastBytes) / dt;
                    if (rate > peakRate) peakRate = rate;
                    lastBytes = tb;
                    lastElapsed = el;
                }
            }
            sw.Stop();
            total = Interlocked.Read(ref totalBytes);
            secs = sw.Elapsed.TotalSeconds;
            double finalDt = secs - lastElapsed;
            if (finalDt > 0.2)
            {
                double r = (total - lastBytes) / finalDt;
                if (r > peakRate) peakRate = r;
            }
            peak = peakRate;
            if (errors.Count > 0 && total == 0)
            {
                lock (errors)
                {
                    Console.WriteLine("      [err] " + (errors.Count == 1 ? errors[0] :
                        errors[0] + " (+" + (errors.Count - 1) + " more)"));
                }
            }
        }

        private static void RunBench(int mode, int iters, int[] streamCounts, string csvPath)
        {
            string err;
            bool aborted = false;
            Process proc = StartTorAndWait(mode, ResolveStrategy(), false, out err, out aborted);
            if (proc == null)
            {
                if (aborted) { Cleanup(); return; }
                Console.WriteLine("[x] " + err);
                Cleanup();
                return;
            }
            try
            {
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
                ServicePointManager.DefaultConnectionLimit = 64;
            }
            catch { }

            Console.WriteLine("bootstrap OK. Warming up 30s (building conflux legs)...");
            Thread.Sleep(30000);
            ProbeBenchUrl();
            if (benchUrl == null)
            {
                Console.WriteLine("[x] aborting bench: no reachable speed endpoint.");
                Cleanup();
                return;
            }

            string variant = Environment.GetEnvironmentVariable("BENCH_VARIANT") ?? "";
            bool writeHeader = !File.Exists(csvPath) || new FileInfo(csvPath).Length == 0;
            var rows = new StringBuilder();
            if (writeHeader)
                rows.AppendLine("ts,variant,mode,streams,avg_mbps,peak_mbps,total_bytes,exit_fp,exit_bw,conflux_sets,conflux_legs");

            foreach (int sc in streamCounts)
            {
                for (int i = 0; i < iters; i++)
                {
                    Console.WriteLine("  [" + (variant.Length > 0 ? variant : ModeNames[mode]) +
                                      "] streams=" + sc + " iter=" + (i + 1) + " ...");
                    long total;
                    double secs, peak;
                    BenchDownload(sc, 10L * 1024 * 1024, out total, out secs, out peak);
                    double avg = secs > 0 ? total / secs : 0;
                    Console.WriteLine("      avg " + FormatSpeed(avg) + "  peak " + FormatSpeed(peak) +
                                      "  in " + secs.ToString("0.0") + " s");
                    int cSets, cLegs;
                    string exit = ConfluxInfo(out cSets, out cLegs);
                    string bw = ExitBandwidth(exit);
                    rows.AppendLine(string.Join(",",
                        DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss"),
                        Csv(variant), ModeNames[mode], sc.ToString(),
                        (avg / (1024 * 1024)).ToString("0.000"),
                        (peak / (1024 * 1024)).ToString("0.000"),
                        total.ToString(), exit, bw, cSets.ToString(), cLegs.ToString()));
                }
            }
            try { File.AppendAllText(csvPath, rows.ToString(), new UTF8Encoding(false)); }
            catch (Exception ex) { Console.WriteLine("[x] failed to write CSV: " + ex.Message); }
            Console.WriteLine("CSV appended to " + csvPath);

            int s2, l2;
            string e2 = ConfluxInfo(out s2, out l2);
            Console.WriteLine("conflux at end: " + s2 + " set(s), " + l2 + " leg(s), exit " + e2);
            Cleanup();
        }

        private static string Csv(string s)
        {
            if (s.IndexOfAny(new[] { ',', '"', '\n', '\r' }) < 0) return s;
            return "\"" + s.Replace("\"", "\"\"") + "\"";
        }

        private static int[] ParseInts(string s)
        {
            var list = new List<int>();
            foreach (string p in s.Split(','))
            {
                int n;
                if (int.TryParse(p.Trim(), out n) && n >= 1) list.Add(n);
            }
            if (list.Count == 0) list.Add(1);
            return list.ToArray();
        }

        private static int StopTor()
        {
            Process p = FindTor();
            if (p != null)
            {
                try { p.Kill(); p.WaitForExit(5000); } catch { }
                SetSystemProxy(false);
                Console.WriteLine("Tor stopped; system proxy restored.");
            }
            else
            {
                Console.WriteLine("No tor from this folder is running.");
            }
            return 0;
        }

        // --- startup port check --------------------------------------------
        // If the TorJet ports are already occupied, a previous tor instance is
        // still running: stop it (and any leftover TUN/system proxy), then carry
        // on with a fresh start instead of refusing to launch.
        private static bool TcpPortBusy(int port)
        {
            TcpListener l = null;
            try
            {
                l = new TcpListener(IPAddress.Loopback, port);
                l.Start();
                return false;
            }
            catch (SocketException) { return true; }
            finally
            {
                if (l != null) try { l.Stop(); } catch { }
            }
        }

        private static bool UdpPortBusy(int port)
        {
            try
            {
                using (UdpClient u = new UdpClient(new IPEndPoint(IPAddress.Loopback, port)))
                { }
                return false;
            }
            catch (SocketException) { return true; }
        }

        private static bool PreviousRunActive()
        {
            foreach (int p in TcpPorts)
                if (TcpPortBusy(p)) return true;
            if (UdpPortBusy(UdpDnsPort)) return true;
            if (ReadFragmentSetting() && TcpPortBusy(FragmentSocksPort)) return true;
            return false;
        }

        private static void StopPreviousRun()
        {
            Process running = FindTor();
            bool prev = running != null || PreviousRunActive();
            if (!prev && !TunActive()) return;

            Console.WriteLine("  A previous TorJet run is still active - stopping it.");

            if (TunActive())
            {
                Console.WriteLine("  Stopping previous TUN...");
                try { File.WriteAllText(TunStopFile, "stop", new UTF8Encoding(false)); } catch { }
                for (int i = 0; i < 16 && TunActive(); i++) Thread.Sleep(500);
                if (TunActive())
                    try { SpawnElevated("off", true); } catch { }
            }

            if (prev)
            {
                var victims = new List<Process>();
                try
                {
                    foreach (Process p in Process.GetProcessesByName("tor"))
                    {
                        try
                        {
                            string path;
                            try { path = p.MainModule.FileName; }
                            catch { path = null; }
                            if (path == null ||
                                StringComparer.OrdinalIgnoreCase.Equals(
                                    Path.GetFullPath(path), Path.GetFullPath(TorExe)))
                                victims.Add(p);
                        }
                        catch { }
                    }
                }
                catch { }
                if (running != null && !victims.Exists(v => v.Id == running.Id))
                    victims.Add(running);
                foreach (Process p in victims)
                {
                    try
                    {
                        Console.WriteLine("  Stopping previous tor (PID " + p.Id + ")...");
                        p.Kill();
                        p.WaitForExit(5000);
                    }
                    catch { }
                }
                Thread.Sleep(1500);
            }

            if (FindXray() != null)
            {
                Console.WriteLine("  Stopping previous xray (fragment)...");
                StopXray();
            }

            SetSystemProxy(false);
        }

        // Runs one Tor session: writes torrc, boots tor with a live progress
        // bar, then serves the P/T/S/C keys until the user presses C or tor
        // dies. Returns 0 (clean exit), 1 (error) or 2 (return to main menu).
        private static int RunTorSession(int mode, int strategy, bool fragment,
                                         bool genOnly, bool bootstrapOnly, string autoMode,
                                         bool menuReturn)
        {
            if (!File.Exists(TorExe))
            {
                Console.WriteLine("[x] tor.exe not found in " + DataDir);
                WaitForKey();
                return 1;
            }
            if (genOnly)
            {
                if (!WriteTorrc(mode, strategy, fragment)) { WaitForKey(); return 1; }
                Console.WriteLine("torrc written only (test mode, tor not started): " + Torrc);
                return 0;
            }

            string startErr;
            bool aborted = false;
            torProc = StartTorAndWait(mode, strategy, fragment, out startErr, out aborted);
            if (torProc == null)
            {
                if (aborted)
                {
                    Console.WriteLine();
                    Console.WriteLine("  Stopping Tor...");
                    Cleanup();
                    cleaned = false;
                    Console.WriteLine("  Tor stopped; system proxy restored.");
                    Console.WriteLine();
                    return 2;
                }
                Console.WriteLine("[x] " + startErr);
                Cleanup();
                cleaned = false;
                if (menuReturn)
                {
                    Console.WriteLine();
                    Console.WriteLine("Press any key to return to the menu...");
                    try { Console.ReadKey(true); } catch { }
                    return 2;
                }
                WaitForKey();
                return 1;
            }

            Console.WriteLine();
            Console.WriteLine("Bootstrapped 100% - Tor is UP.");
            Console.WriteLine();

            if (bootstrapOnly)
            {
                Console.WriteLine("Test mode: stopping tor (no proxy change).");
                Cleanup();
                return 0;
            }

            circuitWatchStop = false;
            circuitWatchWarmup = true;
            if (circuitWatchEnabled)
            {
                Thread watcher = new Thread(CircuitWatchLoop) { IsBackground = true };
                watcher.Start();
                Console.WriteLine("circuit monitor: watching every " + watchIntervalS +
                                  " s, closing the weakest half of legs above " + watchRttMs +
                                  " ms RTT (cooldown " + watchCooldownS +
                                  " s, relaxed during warmup).");
            }

            // Warm the tunnel while the circuit monitor runs with the close
            // cooldown relaxed, so weak legs are replaced right away.
            bool tunnelReady = WarmupTunnel();
            circuitWatchWarmup = false;
            if (!tunnelReady)
            {
                Console.WriteLine("  Stopping Tor...");
                Cleanup();
                cleaned = false;
                torProc = null;
                Console.WriteLine("  Tor stopped; system proxy restored.");
                Console.WriteLine();
                return 2;
            }

            bool proxyOn = false;
            if (autoMode == "proxy")
            {
                proxyOn = true;
                SetSystemProxy(true);
                Console.WriteLine("  System proxy ON  (127.0.0.1:8118)");
            }
            else if (autoMode == "tun")
            {
                if (TunActive())
                    Console.WriteLine("  TUN already ON");
                else
                    ToggleTun();
            }
            Console.WriteLine("  P  :  toggle the Windows system proxy on/off");
            Console.WriteLine("  T  :  toggle TUN mode (all traffic through Tor)");
            Console.WriteLine("  S  :  run a speed test through the Tor proxy");
            Console.WriteLine("  A  :  add a leg to a conflux set");
            Console.WriteLine("  L  :  show conflux set status");
            Console.WriteLine("  C  :  stop Tor and return to the menu");
            Console.WriteLine();
            while (true)
            {
                bool alive = true;
                if (torProc != null)
                {
                    try { torProc.Refresh(); alive = !torProc.HasExited; }
                    catch { alive = false; }
                }
                if (!alive)
                {
                    Console.WriteLine("[x] tor exited with code " + (torProc != null ? torProc.ExitCode : -1) + ".");
                    break;
                }
                try
                {
                    if (Console.KeyAvailable)
                    {
                        ConsoleKeyInfo ki = Console.ReadKey(true);
                        if (ki.Key == ConsoleKey.P)
                        {
                            proxyOn = !proxyOn;
                            SetSystemProxy(proxyOn);
                            Console.WriteLine("  System proxy " + (proxyOn ? "ON  (127.0.0.1:8118)" : "OFF"));
                        }
                        else if (ki.Key == ConsoleKey.S)
                        {
                            SpeedTestMenu();
                        }
                        else if (ki.Key == ConsoleKey.A)
                        {
                            lock (consoleLock) AddConfluxLeg(null);
                        }
                        else if (ki.Key == ConsoleKey.L)
                        {
                            lock (consoleLock) ConfluxStatus();
                        }
                        else if (ki.Key == ConsoleKey.T)
                        {
                            ToggleTun();
                        }
                        else if (ki.Key == ConsoleKey.C)
                        {
                            Console.WriteLine();
                            Console.WriteLine("  Stopping Tor...");
                            Cleanup();
                            cleaned = false;
                            torProc = null;
                            Console.WriteLine("  Tor stopped; system proxy restored.");
                            Console.WriteLine();
                            return 2;
                        }
                    }
                }
                catch { }
                Thread.Sleep(150);
            }

            Cleanup();
            cleaned = false;
            Console.WriteLine("Tor stopped; system proxy restored.");
            WaitForKey();
            return 0;
        }

        // --- version / background update check ------------------------------
        // Compares dotted versions (1.2.3); non-numeric parts are treated as 0.
        private static int CompareVersions(string a, string b)
        {
            string[] pa = a.Split('.');
            string[] pb = b.Split('.');
            int n = Math.Max(pa.Length, pb.Length);
            for (int i = 0; i < n; i++)
            {
                int x = i < pa.Length ? VersionPart(pa[i]) : 0;
                int y = i < pb.Length ? VersionPart(pb[i]) : 0;
                if (x != y) return x.CompareTo(y);
            }
            return 0;
        }

        private static int VersionPart(string s)
        {
            int v;
            if (int.TryParse(s, out v)) return v;
            Match m = Regex.Match(s, @"^\d+");
            return m.Success ? int.Parse(m.Value) : 0;
        }

        // Queries the GitHub latest release; prints the download link when a
        // newer version than the embedded one exists.
        private static void CheckForUpdates()
        {
            try { ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12; }
            catch { }
            try
            {
                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(
                    "https://api.github.com/repos/Delta-Kronecker/TorJet/releases/latest");
                req.UserAgent = "torjet-update-check/" + TorJetVersion.App;
                req.Timeout = 8000;
                req.ReadWriteTimeout = 8000;
                using (WebResponse resp = req.GetResponse())
                using (StreamReader sr = new StreamReader(resp.GetResponseStream()))
                {
                    Match m = Regex.Match(sr.ReadToEnd(), "\"tag_name\"\\s*:\\s*\"([^\"]+)\"");
                    if (m.Success)
                    {
                        string latest = m.Groups[1].Value.TrimStart('v', 'V');
                        if (CompareVersions(latest, TorJetVersion.App) > 0)
                        {
                            updatePromptShown = true;
                            Console.WriteLine();
                            Console.WriteLine("  New TorJet version available: v" + latest +
                                              " (you have v" + TorJetVersion.App + ")");
                            Console.WriteLine("      Download: https://github.com/Delta-Kronecker/TorJet/releases/latest");
                            Console.WriteLine();
                        }
                    }
                }
            }
            catch { }
        }

        private static void UpdateCheckLoop()
        {
            while (true)
            {
                if (!updatePromptShown) CheckForUpdates();
                Thread.Sleep(TimeSpan.FromMinutes(30));
            }
        }

        private static int Main(string[] args)
        {
            Console.Title = "TorJet";
            Console.CancelKeyPress += delegate(object sender, ConsoleCancelEventArgs e)
            {
                e.Cancel = true;
                Cleanup();
                Environment.Exit(0);
            };

            Thread updater = new Thread(UpdateCheckLoop) { IsBackground = true };
            updater.Start();

            if (args.Length > 0 && args[0] == "--conflux-status")
            {
                return ConfluxStatus();
            }
            if (args.Length > 0 && args[0] == "--conflux-add")
            {
                return AddConfluxLeg(args.Length > 1 ? args[1] : null);
            }
            if (args.Length > 0 && args[0] == "--conflux-check")
            {
                int m = -1;
                for (int i = 1; i < args.Length; i++) { int mm = ParseMode(args[i]); if (mm >= 0) m = mm; }
                if (m < 0) m = ShowMenu();
                if (m < 0) { Console.WriteLine("[x] no mode selected."); return 1; }
                string err;
                bool aborted = false;
                Process p = StartTorAndWait(m, ResolveStrategy(), false, out err, out aborted);
                if (p == null) { if (aborted) { Cleanup(); return 1; } Console.WriteLine("[x] " + err); Cleanup(); return 1; }
                Console.WriteLine("bootstrap OK. Waiting 30s for conflux sets to build...");
                Thread.Sleep(30000);
                int code = ConfluxStatus();
                Cleanup();
                return code;
            }
            if (args.Length > 0 && args[0] == "--bench")
            {
                int bMode = -1;
                int iters = 3;
                int[] streams = { 1, 4, 8 };
                string csvPath = "bench.csv";
                for (int i = 1; i < args.Length; i++)
                {
                    if (args[i] == "--iters" && i + 1 < args.Length) { int.TryParse(args[++i], out iters); }
                    else if (args[i] == "--streams" && i + 1 < args.Length) { streams = ParseInts(args[++i]); }
                    else if (args[i] == "--csv" && i + 1 < args.Length) { csvPath = args[++i]; }
                    else { int mm = ParseMode(args[i]); if (mm >= 0) bMode = mm; }
                }
                if (bMode < 0) bMode = ShowMenu();
                if (bMode < 0) return 1;
                RunBench(bMode, iters, streams, csvPath);
                return 0;
            }
            if (args.Length > 0 && args[0] == "--newcircuit")
            {
                Console.WriteLine(ControlSend("SIGNAL NEWNYM")
                    ? "New identity requested (NEWNYM)."
                    : "No tor control port on 127.0.0.1:9051. Is tor running?");
                return 0;
            }
            if (args.Length > 0 && args[0] == "--stop")
            {
                return StopTor();
            }
            if (args.Length > 0 &&
                (args[0] == "--update-bridges" || args[0] == "--update" || args[0] == "-u"))
            {
                return UpdateBridges();
            }
            if (args.Length > 0 && args[0] == "--tun-off")
            {
                if (!TunActive())
                {
                    Console.WriteLine("TUN OFF");
                    return 0;
                }
                TurnTunOff();
                return TunActive() ? 1 : 0;
            }
            if (args.Length > 0 && args[0] == "--tun-status")
            {
                Console.WriteLine("TUN " + (TunActive() ? "ON" : "OFF"));
                return 0;
            }

            int mode = -1;
            int strategy = -1;
            bool bootstrapOnly = false;
            bool genOnly = false;
            bool newCircuit = false;
            bool fragment = ReadFragmentSetting();
            string autoMode = "";
            for (int i = 0; i < args.Length; i++)
            {
                string a = args[i];
                if (a == "--bootstrap-only" || a == "-t") bootstrapOnly = true;
                else if (a == "--gen-torrc-only") genOnly = true;
                else if (a == "--strategy" && i + 1 < args.Length) strategy = ParseStrategy(args[++i]);
                else if (a == "--strategy") strategy = ParseStrategy(a);
                else if (a == "--newcircuit") newCircuit = true;
                else if (a == "--fragment") fragment = true;
                else if (a == "--no-fragment") fragment = false;
                else if (a == "--circuit-watch") circuitWatchEnabled = true;
                else if (a == "--no-circuit-watch") circuitWatchEnabled = false;
                else if (a == "--watch-rtt" && i + 1 < args.Length) { int.TryParse(args[++i], out watchRttMs); }
                else if (a == "--watch-interval" && i + 1 < args.Length) { int.TryParse(args[++i], out watchIntervalS); }
                else if (a == "--watch-cooldown" && i + 1 < args.Length) { int.TryParse(args[++i], out watchCooldownS); }
                else if (a == "--warmup" && i + 1 < args.Length) { int.TryParse(args[++i], out warmupSeconds); }
                else if (a == "proxy" || a == "--proxy") autoMode = "proxy";
                else if (a == "tun" || a == "--tun") autoMode = "tun";
                else
                {
                    int m = ParseMode(a);
                    if (m >= 0) { mode = m; continue; }
                    int s = ParseStrategy(a);
                    if (s >= 0) strategy = s;
                }
            }
            if (newCircuit)
            {
                Console.WriteLine(ControlSend("SIGNAL NEWNYM")
                    ? "New identity requested (NEWNYM)."
                    : "No tor control port on 127.0.0.1:9051. Is tor running?");
                return 0;
            }
            if (mode < 0)
            {
                while (true)
                {
                    ShowMainMenu(out mode, out strategy, out fragment);
                    if (mode < 0) return 0;
                    int rc = RunTorSession(mode, strategy, fragment, genOnly, bootstrapOnly, autoMode, true);
                    if (rc != 2) return rc;
                }
            }
            else
            {
                if (strategy < 0) strategy = ReadLastStrategy();
                if (strategy < 0) strategy = 0;
                while (true)
                {
                    int rc = RunTorSession(mode, strategy, fragment, genOnly, bootstrapOnly, autoMode, true);
                    if (rc != 2) return rc;
                    ShowMainMenu(out mode, out strategy, out fragment);
                    if (mode < 0) return 0;
                }
            }
        }
    }
}
